head.script:
scwin.gVar = {
    "cInitClass" : null,
    "cInitStyle" : ""
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[body > M > setStyle]<br/>컴포넌트의 특정 CSS 속성값을 변경합니다.",
    "validation" : [
        "property(필수) 파라미터로 값을 변경하려는 CSS 속성의 이름을 문자열로 설정할 수 있어야 합니다.",
        "'borderLeft' 와 같은 camelCase 형식으로 설정할 수 있어야 합니다.",
        "value(필수) 파라미터로 해당 CSS 속성에 적용할 값을 문자열로 설정수 있어야 합니다.",
        "value(필수) 파라미터를 숫자로 설정하면 기본 단위(px)가 적용되어야 합니다.",
        "색상과 관련된 CSS 속성은 '#rrggbb', 'rgb(255,0,255)', 'rgba(255,0,255,0.5)' 등 다양한 형식으로 설정할 수 있어야 합니다.",
        "단위나 공백이 포함된 값('10em', '50%' 등)은 문자열로 설정할 수 있어야 합니다.",  
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};




// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  body 는 동적 생성/삭제가 불가하므로 최초 렌더된 body 컴포넌트를 그대로 대상으로 사용하고,
//  "Target 재생성" 은 최초 렌더 시점의 class / style 상태로 되돌리는 것으로 대응한다.
scwin.comp_init = function () {
    let objBody = scwin.getBody();

    if (scwin.gVar["cInitClass"] === null) {
        // 최초 1회 : 초기 class / style 보관
        scwin.gVar["cInitClass"] = objBody.render.className;
        scwin.gVar["cInitStyle"] = objBody.render.getAttribute("style") || "";
    } else {
        // 재생성 : 초기 상태로 복원
        objBody.render.className = scwin.gVar["cInitClass"];
        objBody.render.setAttribute("style", scwin.gVar["cInitStyle"]);
    }
}



scwin.btn_getStyle_onclick = function (e) {
    let rtn = '';

    rtn = scwin.getBody().getStyle(par_property_get.getText());
    wf_body_bottom.getObj("scwin").setReturnValue("getStyle : " + rtn);
};



scwin.btn_setStyle_onclick = function (e) {
    scwin.getBody().setStyle(par_property_set.getText(), par_value_set.getValue());

    scwin.btn_getStyle_onclick();
};



scwin.par_property_onchange = function (info) {
    let prt = par_property_set.getText();

    if (prt == "background-color") {
        par_value_set.setValue("rgb(255,0,255)");
        par_property_get.setSelectedIndex(0);
    }        
    else if (prt == "border") {
        par_value_set.setValue("1px solid black");
        par_property_get.setSelectedIndex(1);
    }        
    else if (prt == "opacity") {
        par_value_set.setValue("50%");
        par_property_get.setSelectedIndex(2);
    }        
    else if (prt == "line-height") {
        par_value_set.setValue(1);
        par_property_get.setSelectedIndex(3);
    }            
    else if (prt == "backgroundColor") {
        par_value_set.setValue("rgb(255,255,0, 0.5)");
        par_property_get.setSelectedIndex(0);
    }        
};


// body 컴포넌트 조회
//  body 는 화면과 함께 렌더되는 컴포넌트로 $p.dynamicCreate / remove 대상이 아니고
//  공통 생성 함수($c.gcm.createBasicXxx)도 없어 공통 base(common_M) wrap 패턴을 쓸 수 없다.
//  <body id="target1"> 로 선언해도 body 는 root 요소라 scope 전역(target1)으로 등록되지 않으며
//  $p.getComponentById("target1") 도 scope 접두어가 적용되지 않아 undefined 를 반환하므로,
//  정적 선언된 자식(grp_main)의 parentControl 로 조회한다.
scwin.getBody = function () {
    return grp_main.parentControl;
}
